        }
    });

    let m2 = Arc::clone(&m);
    let c2 = Arc::clone(&c);
    let w2 = thread::spawn(move || {
        let _guard = m2.lock().unwrap();
        let mut val = c2.lock().unwrap();
        if *val < 1 {
            *val += 1;
        }
    });

    w1.join().unwrap();
    w2.join().unwrap();

    let done = *c.lock().unwrap();
    println!("DONE done={}", done);
}
