    v
}

fn worker(m: Arc<Mutex<u64>>, acc: Arc<Mutex<u64>>) {
    let mut guard = m.lock().unwrap();
    let local = compute(*guard);
    *guard = local;
    let mut a = acc.lock().unwrap();
    *a += 1;
    drop(a);
    drop(guard);
}

fn main() {
    let m = Arc::new(Mutex::new(1u64));
    let acc = Arc::new(Mutex::new(0u64));

    let m1 = Arc::clone(&m);
    let acc1 = Arc::clone(&acc);
    let w1 = thread::spawn(move || worker(m1, acc1));

    let m2 = Arc::clone(&m);
    let acc2 = Arc::clone(&acc);
    let w2 = thread::spawn(move || worker(m2, acc2));

    w1.join().unwrap();
    w2.join().unwrap();

    let done = *acc.lock().unwrap();
    println!("DONE done={}", done);
}
